import { z } from "zod";

export default z
  .object({
    type: z.literal("message_created"),
    data: z
      .object({
        id: z.string().describe("Identifier of the [Message](#schema_message)"),
        createdAt: z
          .string()
          .datetime()
          .describe(
            "Creation date of the [Message](#schema_message) in ISO 8601 format"
          ),
        payload: z
          .union([
            z.object({ type: z.literal("audio"), audioUrl: z.string().min(1) }),
            z.object({
              type: z.literal("card"),
              title: z.string().min(1),
              subtitle: z.string().min(1).optional(),
              imageUrl: z.string().min(1).optional(),
              actions: z.array(
                z.object({
                  action: z.enum(["postback", "url", "say"]),
                  label: z.string().min(1),
                  value: z.string().min(1),
                })
              ),
            }),
            z.object({
              type: z.literal("carousel"),
              items: z.array(
                z.object({
                  type: z.literal("card"),
                  title: z.string().min(1),
                  subtitle: z.string().min(1).optional(),
                  imageUrl: z.string().min(1).optional(),
                  actions: z.array(
                    z.object({
                      action: z.enum(["postback", "url", "say"]),
                      label: z.string().min(1),
                      value: z.string().min(1),
                    })
                  ),
                })
              ),
            }),
            z.object({
              text: z.string().min(1),
              options: z.array(
                z.object({ label: z.string().min(1), value: z.string().min(1) })
              ),
              type: z.literal("choice"),
            }),
            z.object({
              text: z.string().min(1),
              options: z.array(
                z.object({ label: z.string().min(1), value: z.string().min(1) })
              ),
              type: z.literal("dropdown"),
            }),
            z.object({
              type: z.literal("file"),
              fileUrl: z.string().min(1),
              title: z.string().min(1).optional(),
            }),
            z.object({ type: z.literal("image"), imageUrl: z.string().min(1) }),
            z.object({
              type: z.literal("location"),
              latitude: z.number(),
              longitude: z.number(),
              address: z.string().optional(),
              title: z.string().optional(),
            }),
            z.object({ type: z.literal("text"), text: z.string().min(1) }),
            z.object({ type: z.literal("video"), videoUrl: z.string().min(1) }),
            z.object({
              type: z.literal("markdown"),
              markdown: z.string().min(1),
            }),
            z.object({
              type: z.literal("bloc"),
              items: z.array(
                z.union([
                  z.object({
                    type: z.literal("text"),
                    text: z.string().min(1),
                  }),
                  z.object({
                    type: z.literal("markdown"),
                    markdown: z.string().min(1),
                  }),
                  z.object({
                    type: z.literal("image"),
                    imageUrl: z.string().min(1),
                  }),
                  z.object({
                    type: z.literal("audio"),
                    audioUrl: z.string().min(1),
                  }),
                  z.object({
                    type: z.literal("video"),
                    videoUrl: z.string().min(1),
                  }),
                  z.object({
                    type: z.literal("file"),
                    fileUrl: z.string().min(1),
                    title: z.string().min(1).optional(),
                  }),
                  z.object({
                    type: z.literal("location"),
                    latitude: z.number(),
                    longitude: z.number(),
                    address: z.string().optional(),
                    title: z.string().optional(),
                  }),
                ])
              ),
            }),
          ])
          .describe("Payload is the content type of the message."),
        userId: z.string().describe("ID of the [User](#schema_user)"),
        conversationId: z
          .string()
          .describe("ID of the [Conversation](#schema_conversation)"),
        metadata: z
          .record(z.union([z.any(), z.null()]))
          .describe("Metadata of the message")
          .optional(),
        isBot: z
          .boolean()
          .describe("Whether the message was created by the bot or not"),
      })
      ,
  })
  ;
